export const SITE_DEF = {"prods": [{"id": 1, "cat": "rebar", "n": {"uk": "Фіксатор «Настил»", "en": "Slab chair “Nastil”"}, "d": {"uk": "Забезпечує проєктну висоту захисного шару бетону під горизонтальною арматурою на сипкій основі: ґрунті, щебені, піску, а також на мембрані чи плівці. Збільшена площа основи не дає виробу занурюватися.", "en": "Sets the design concrete cover under horizontal rebar on loose bases: soil, gravel, sand, membranes and films. The enlarged base keeps the part from sinking."}, "u": "pc", "v": [["25-30", "1.728", 300], ["30-40", "1.480", 200], ["50-60", "1.728", 200], ["70-80", "1.860", 150], ["90-100", "1.980", 150]], "sp": [["Призначення", "Purpose", "Сипуча основа", "Loose base"], ["Тип", "Type", "Стійка", "Chair"], ["Матеріал", "Material", "Пластик", "Plastic"], ["Робоче положення", "Working position", "Горизонтальне", "Horizontal"]], "on": true}, {"id": 2, "cat": "rebar", "n": {"uk": "Фіксатор «Стійка»", "en": "Rebar chair “Stiika”"}, "d": {"uk": "Тримає арматуру в горизонтальному положенні в плитах перекриття, стяжках і промислових підлогах на бетонній чи іншій твердій основі. Конструкція розподіляє навантаження по всій площі й витримує тиск арматурного каркаса.", "en": "Keeps rebar level in floor slabs, screeds and industrial floors on concrete or another solid base. The design spreads the load across the footprint and withstands the pressure of the rebar cage."}, "u": "pc", "v": [["20-25-30", "1.728", 300], ["25-30", "1.480", 200], ["35-40", "1.728", 200], ["35-40-35", "1.860", 150]], "sp": [["Витрата", "Consumption", "4–6 шт/м²", "4–6 pcs/m²"], ["Тип", "Type", "Стійка", "Chair"], ["Матеріал", "Material", "Пластик", "Plastic"], ["Робоче положення", "Working position", "Горизонтальне", "Horizontal"]], "on": true}, {"id": 3, "cat": "rebar", "n": {"uk": "Фіксатор «Зірочка»", "en": "Star spacer “Zirochka”"}, "d": {"uk": "Створює захисний шар для вертикальної арматури діаметром 6–16 мм у стінах, колонах і стовпах, а також у кутових горизонтальних каркасах. Міцний еластичний замок дозволяє працювати з арматурою різного діаметра.", "en": "Creates the concrete cover for vertical rebar of 6–16 mm in walls, columns and pillars, and in corner horizontal cages. A strong elastic lock fits rebar of different diameters."}, "u": "pc", "v": [["15/6-12", "1.728", 2000], ["25/6-12", "0.504", 1000], ["25/4-20", "0.630", 500], ["30/8-20", "0.804", 500], ["35/6-12", "0.960", 500], ["40/14-20", "1.260", 200], ["50/12-20", "1.608", 200]], "sp": [["Арматура", "Rebar", "Ø 6–16 мм", "Ø 6–16 mm"], ["Застосування", "Use", "Вертикальні елементи", "Vertical elements"], ["Матеріал", "Material", "Пластик", "Plastic"]], "on": true}, {"id": 4, "cat": "rebar", "n": {"uk": "Фіксатор «Защіпка»", "en": "Clip spacer “Zashchipka”"}, "d": {"uk": "Фіксує арматуру в горизонтальному положенні при влаштуванні плит перекриття, стяжок і промислових підлог на бетонній поверхні.", "en": "Holds rebar horizontally in floor slabs, screeds and industrial floors on a concrete surface."}, "u": "pc", "v": [["15/10", "0.456", 1000], ["20/10", "0.480", 1000], ["25/10", "0.528", 1000]], "sp": [["Витрата", "Consumption", "4–6 шт/м²", "4–6 pcs/m²"], ["Матеріал", "Material", "Пластик", "Plastic"], ["Робоче положення", "Working position", "Горизонтальне", "Horizontal"]], "on": true}, {"id": 5, "cat": "rebar", "n": {"uk": "Фіксатор «Засувка»", "en": "Slide spacer “Zasuvka”"}, "d": {"uk": "Фіксує арматуру на бетонній основі в плитах перекриття, стяжках і промислових підлогах. Конструкція розподіляє навантаження по площі виробу й надійно витримує тиск арматурного каркаса.", "en": "Holds rebar on a concrete base in slabs, screeds and industrial floors. The design spreads the load and reliably withstands the pressure of the rebar cage."}, "u": "pc", "v": [["50/8-24", "1.98", 250]], "sp": [["Тип", "Type", "Стійка", "Chair"], ["Матеріал", "Material", "Пластик", "Plastic"], ["Робоче положення", "Working position", "Горизонтальне", "Horizontal"]], "on": true}, {"id": 6, "cat": "form", "n": {"uk": "Фіксатор «Конус»", "en": "Cone spacer “Konus”"}, "d": {"uk": "Надягається на ПВХ- або поліетиленову трубку діаметром 22 мм і захищає елементи опалубки від впливу бетону, збільшуючи площу контакту зі щитом. Не допускає затікання бетону в трубку й потрапляння його на стяжний гвинт; стійкий до навантажень, агресивного середовища та перепаду температур.", "en": "Fits a 22 mm PVC or PE tube and protects formwork elements from concrete, increasing the contact area with the panel. Keeps concrete out of the tube and off the tie rod; resistant to loads, aggressive environments and temperature swings."}, "u": "pc", "v": [["22", "0.444", 1000]], "sp": [["Діаметр трубки", "Tube diameter", "22 мм", "22 mm"], ["Матеріал", "Material", "Пластик", "Plastic"]], "on": true}, {"id": 7, "cat": "form", "n": {"uk": "Фіксатор «Корок-ялинка»", "en": "Fir-tree plug"}, "d": {"uk": "Універсальний корок для закриття невикористаних отворів під анкерні стрижні в опалубці, а також отворів у стінах після демонтажу опалубки.", "en": "A universal plug that closes unused anchor-rod holes in formwork, as well as holes left in walls after the formwork is removed."}, "u": "pc", "v": [["24", "0.84", 1000]], "sp": [["Матеріал", "Material", "Пластик", "Plastic"]], "on": true}, {"id": 8, "cat": "form", "n": {"uk": "Фіксатор «Корок»", "en": "Plug “Korok”"}, "d": {"uk": "Пластикова заглушка циліндричної форми. Запобігає затіканню бетонної суміші в монтажні отвори опалубних щитів і герметизує отвори в монолітних конструкціях.", "en": "A cylindrical plastic plug. Keeps concrete mix out of the mounting holes in formwork panels and seals holes in monolithic structures."}, "u": "pc", "v": [["24", "0.60", 1000]], "sp": [["Матеріал", "Material", "Пластик", "Plastic"]], "on": true}, {"id": 9, "cat": "form", "n": {"uk": "Фіксатор «Труба»", "en": "Spacer tube"}, "d": {"uk": "Утримує відстань між опалубними щитами при влаштуванні колон і пілонів та не допускає потрапляння бетону на стяжний гвинт під час заливання. Гвинт легко виймається з конструкції. Доступна з поліетилену (П/Е) і ПВХ.", "en": "Keeps the distance between formwork panels when casting columns and pylons and prevents concrete from reaching the tie rod during pouring. The rod is easy to remove. Available in PE and PVC."}, "u": "m", "v": [[["П/Е", "PE"], "10.60", 100], [["ПВХ", "PVC"], "13.50", 100]], "sp": [["Матеріал", "Material", "П/Е, ПВХ", "PE, PVC"], ["Стійкість", "Resistance", "До навантажень, агресивного середовища, перепаду температур", "Loads, aggressive environments, temperature swings"]], "on": true}], "posts": [{"id": 5, "st": "pub", "date": "2026-10-20", "t": ["Конуси, корки й дистанційні труби для опалубки: як закрити отвори від стяжних гвинтів", "Formwork cones, plugs and spacer tubes: how to seal tie-rod holes"], "e": ["Як працює стяжка опалубки, навіщо потрібні дистанційна труба, конус і корок, як підібрати комплект і правильно закрити отвори в монолітних стінах.", "How formwork ties work, what spacer tubes, cones and plugs do, how to pick a set and how to seal holes in cast-in-place walls properly."], "b": [[["p", "Під час бетонування монолітних стін і колон щити опалубки стягують між собою стяжними гвинтами, які проходять крізь майбутню конструкцію. Після набору міцності бетону гвинти потрібно витягти, а отвори — закрити. Саме для цього існують дистанційні труби, конуси та корки."], ["p", "Це недорогі вироби, але від них залежить, чи вдасться легко демонтувати опалубку, чи не потече бетон крізь щити і як виглядатиме стіна після розпалублення. Розбираємо, як працює кожен елемент і як зібрати правильний комплект. Усі вироби є в нашому <a href=\"/fiksatory-dlia-opalubky\" data-go=\"catalog\" data-a=\"form\">каталозі фіксаторів для опалубки</a>."], ["h2", "Як влаштована стяжка опалубки"], ["p", "Щити опалубки встановлюють з обох боків майбутньої стіни. Щоб тиск свіжого бетону не розсунув їх, щити з’єднують стяжними гвинтами (тяжами) з гайками. Гвинт проходить крізь бетон — і якщо він опиниться в ньому «голим», витягти його буде неможливо. Тому гвинт пропускають усередині пластикової труби, а на її кінцях встановлюють конуси."], ["h2", "Дистанційна труба"], ["p", "<a href=\"/dystantsiina-truba\" data-go=\"product\" data-a=\"9-0\">Дистанційна труба</a> виконує дві функції: утримує проєктну відстань між щитами, тобто товщину стіни, і захищає стяжний гвинт від контакту з бетоном. Після бетонування гвинт легко виймається, а труба залишається в стіні."], ["p", "Труби виготовляють із поліетилену (П/Е) або ПВХ. Обидва матеріали стійкі до навантажень, агресивного середовища й перепадів температур. Довжину труби розраховують за товщиною стіни з урахуванням конусів на її кінцях."], ["h2", "Конус"], ["p", "<a href=\"/fiksator-konus\" data-go=\"product\" data-a=\"6-0\">Фіксатор «Конус»</a> надягається на кінець труби діаметром 22 мм і впирається в щит. Він збільшує площу контакту зі щитом, не дає бетону затікати в трубу й потрапляти на гвинт, а після демонтажу формує акуратний конічний вхід отвору, який зручно герметизувати."], ["h2", "Корок і корок-ялинка"], ["p", "Після розпалублення в стіні залишаються отвори. Їх закривають корками:"], ["ul", "<li><a href=\"/fiksator-korok\" data-go=\"product\" data-a=\"8-0\">«Корок»</a> — циліндрична заглушка, яка запобігає затіканню бетону в монтажні отвори опалубних щитів і герметизує отвори в монолітних конструкціях;</li><li><a href=\"/korok-yalynka\" data-go=\"product\" data-a=\"7-0\">«Корок-ялинка»</a> — універсальний корок із ребрами, що закриває невикористані отвори під анкерні стрижні в опалубці, а також отвори в стінах після демонтажу.</li>"], ["p", "Обидва вироби мають діаметр 24 мм — під отвір, сформований конусом."], ["blockquote", "<p>Комплект «труба + два конуси + два корки» на кожну точку стяжки коштує копійки, але саме він визначає, чи будуть стіни чистими й сухими після розпалублення.</p>"], ["h2", "Як підібрати комплект"], ["ol", "<li><b>Визначте систему стяжки.</b> Найпоширеніший варіант для щитової опалубки — гвинт, під який використовують трубку 22 мм. Уточніть параметри у постачальника опалубки.</li><li><b>Порахуйте кількість точок стяжки.</b> Вона визначається системою опалубки: щити мають отвори у фіксованих місцях. Множте кількість точок на щиті на кількість щитів, які встановлюються за одне бетонування, і на кількість захваток.</li><li><b>Розрахуйте довжину труб</b> під товщину кожної стіни.</li><li><b>Порахуйте конуси й корки:</b> по два на кожну трубу — з кожного боку стіни.</li><li><b>Додайте корки-ялинки</b> для невикористаних отворів у щитах.</li><li><b>Закладіть запас</b> 5–10 % на втрати під час монтажу.</li>"], ["cta", "{\"t\": \"Комплектуємо опалубку під ваш об’єкт\", \"d\": \"Труби, конуси й корки зі складу у Львові та Києві — підберемо комплект і порахуємо кількість.\", \"b\": [[\"Фіксатори для опалубки\", \"cat_form\", \"catalog\", \"form\", \"/fiksatory-dlia-opalubky\"], [\"Комплектація об’єктів\", \"srv2\", \"soon\", \"2\", \"/komplektatsiia-obiektiv\"], [\"Запросити розрахунок\", \"rfq\"]]}"], ["h2", "Герметизація отворів у стінах підвалів"], ["p", "Для внутрішніх стін зазвичай достатньо закрити отвір корком. Для стін підвалів, резервуарів та інших конструкцій, що контактують з водою чи ґрунтом, корок поєднують з додатковою гідроізоляцією: отвір заповнюють ремонтним або гідроізоляційним розчином, за проєктом — використовують спеціальні герметики. Конус, сформований фіксатором, полегшує цю роботу: розчин краще тримається в конічному отворі."], ["h2", "Типові помилки"], ["ul", "<li>Гвинт пропускають без труби — потім його доводиться зрізати й залишати в бетоні.</li><li>Не ставлять конуси — бетон затікає в трубу, а на поверхні залишаються напливи.</li><li>Залишають отвори відкритими — у них потрапляє вода, взимку вона замерзає й руйнує бетон.</li><li>Підбирають корки не під діаметр — вони випадають або не входять в отвір.</li>"], ["h2", "Часті питання"], ["h3", "Чи можна використовувати конуси повторно?"], ["p", "Конуси залишаються в стіні разом із трубою або виймаються під час розпалублення залежно від технології. Здебільшого їх розглядають як витратний матеріал."], ["h3", "Що краще: ПВХ чи поліетиленова труба?"], ["p", "Обидва варіанти надійні. Вибір залежить від вимог проєкту й умов роботи; менеджер підкаже оптимальний варіант для вашого об’єкта."], ["h3", "Чи є все це на складі?"], ["p", "Так, ходові позиції є в наявності на складах у Львові та Києві. Доставляємо Новою поштою, вантажними перевізниками або прямо на об’єкт — <a href=\"/dostavka\" data-go=\"delivery\">деталі доставки</a>."], ["h2", "Висновок"], ["p", "Дистанційна труба захищає гвинт і тримає товщину стіни, конус не пускає бетон у трубу й формує акуратний отвір, корок закриває його після розпалублення. Разом вони роблять монтаж і демонтаж опалубки швидким, а стіни — чистими. Якщо вам потрібен комплект на об’єкт, залиште заявку нижче — ми порахуємо кількість і підготуємо пропозицію."]], [["p", "When casting concrete walls and columns, formwork panels are tied together with rods that pass through the future structure. Once the concrete has gained strength, the rods are pulled out and the holes sealed. That is what spacer tubes, cones and plugs are for."], ["p", "They are inexpensive, yet they decide whether formwork strips easily, whether concrete leaks through the panels and how the wall looks afterwards. Here is how each part works and how to build the right set. All parts are in our <a href=\"/en/formwork-accessories\" data-go=\"catalog\" data-a=\"form\">formwork accessories catalog</a>."], ["h2", "How formwork ties work"], ["p", "Panels stand on both sides of the future wall. To stop fresh concrete pressure from pushing them apart, they are connected with tie rods and nuts. A bare rod cast into concrete cannot be removed — so it runs inside a plastic tube with cones at both ends."], ["h2", "Spacer tube"], ["p", "The <a href=\"/en/spacer-tube\" data-go=\"product\" data-a=\"9-0\">spacer tube</a> keeps the panels at the design distance — the wall thickness — and protects the tie rod from concrete. After the pour the rod slides out and the tube stays in the wall."], ["p", "Tubes are made of polyethylene (PE) or PVC; both resist loads, aggressive environments and temperature swings. Tube length is calculated from the wall thickness, allowing for the cones."], ["h2", "Cone"], ["p", "The <a href=\"/en/cone-spacer-konus\" data-go=\"product\" data-a=\"6-0\">“Konus” cone</a> fits onto the end of a 22 mm tube and bears against the panel. It increases the contact area, keeps concrete out of the tube and off the rod and, after stripping, leaves a neat conical hole that is easy to seal."], ["h2", "Plug and fir-tree plug"], ["p", "After stripping, holes remain in the wall. They are closed with plugs:"], ["ul", "<li>the <a href=\"/en/formwork-plug-korok\" data-go=\"product\" data-a=\"8-0\">“Korok” plug</a> — a cylindrical cap that stops concrete entering panel holes and seals holes in cast-in-place structures;</li><li>the <a href=\"/en/fir-tree-plug\" data-go=\"product\" data-a=\"7-0\">fir-tree plug</a> — a ribbed universal plug for unused tie holes in panels and for holes in walls after stripping.</li>"], ["p", "Both are 24 mm — matching the hole formed by the cone."], ["blockquote", "<p>A tube, two cones and two plugs per tie point cost very little, yet they decide whether walls come out clean and dry.</p>"], ["h2", "How to put a set together"], ["ol", "<li><b>Identify the tie system.</b> The most common panel-formwork option uses a 22 mm tube; confirm with your formwork supplier.</li><li><b>Count tie points</b> — fixed by the panel system: holes per panel × panels per pour × number of pours.</li><li><b>Work out tube lengths</b> for each wall thickness.</li><li><b>Count cones and plugs:</b> two per tube, one on each face.</li><li><b>Add fir-tree plugs</b> for unused panel holes.</li><li><b>Allow 5–10 %</b> for losses.</li>"], ["cta", "{\"t\": \"We supply formwork sets for your site\", \"d\": \"Tubes, cones and plugs in stock in Lviv and Kyiv — we will build the set and calculate quantities.\", \"b\": [[\"Formwork accessories\", \"cat_form\", \"catalog\", \"form\", \"/en/formwork-accessories\"], [\"Site supply\", \"srv2\", \"soon\", \"2\", \"/en/construction-supply\"], [\"Request a quote\", \"rfq\"]]}"], ["h2", "Sealing holes in basement walls"], ["p", "For internal walls a plug is usually enough. For basements, tanks and other elements in contact with water or soil, combine the plug with extra waterproofing: fill the hole with repair or waterproofing mortar or a specified sealant. The conical hole formed by the cone helps the mortar key in."], ["h2", "Common mistakes"], ["ul", "<li>Running the rod without a tube — it then has to be cut and left in the concrete.</li><li>Skipping cones — concrete enters the tube and leaves fins on the surface.</li><li>Leaving holes open — water gets in, freezes in winter and damages the concrete.</li><li>Using plugs of the wrong diameter — they fall out or do not fit.</li>"], ["h2", "FAQ"], ["h3", "Can cones be reused?"], ["p", "Depending on the method, cones stay in the wall with the tube or are removed at stripping. They are generally treated as consumables."], ["h3", "PVC or PE tube?"], ["p", "Both are reliable. The choice depends on the project and conditions; our manager will suggest the best option."], ["h3", "Is everything in stock?"], ["p", "Yes, fast-moving items are in stock in Lviv and Kyiv. We ship by Nova Post, freight carriers or straight to site — <a href=\"/en/delivery\" data-go=\"delivery\">delivery details</a>."], ["h2", "Conclusion"], ["p", "The spacer tube protects the rod and sets the wall thickness, the cone keeps concrete out and forms a neat hole, and the plug closes it after stripping. Together they make formwork fast to fit and strip and leave walls clean. Need a set for your site? Leave a request below and we will calculate quantities and send an offer."]]], "tag": ["Будівництво", "Construction"]}, {"id": 1, "st": "pub", "date": "2026-10-14", "t": ["Як обрати фіксатор арматури: види, розміри та витрата на 1 м²", "How to choose a rebar spacer: types, sizes and quantity per m²"], "e": ["Який фіксатор арматури потрібен для плити, фундаменту на ґрунті, стіни чи колони, як підібрати висоту під захисний шар бетону і скільки штук закласти на квадратний метр.", "Which rebar spacer suits a slab, a ground-bearing foundation, a wall or a column, how to size it to the concrete cover and how many to use per square metre."], "b": [[["p", "Фіксатор арматури — невелика пластикова деталь, від якої залежить, чи опиниться арматура там, де її поставив проєктувальник. Саме фіксатори тримають арматурний каркас на заданій висоті, поки по ньому ходять монтажники, поки бетон заливають із бетононасоса й ущільнюють глибинним вібратором. Якщо каркас «сів» хоча б на кілька міліметрів, конструкція втрачає захисний шар, а з ним — частину довговічності."], ["p", "На ринку десятки форм і розмірів, і через це виникає плутанина: що купувати для фундаментної плити на піщаній подушці, а що — для перекриття по профлисту чи для стіни підвалу. У цій статті розбираємо, як вибрати фіксатор арматури за типом основи та конструкції, як підібрати висоту під проєктний захисний шар і як порахувати потрібну кількість на об’єкт. Усі вироби, про які йдеться, PLASTIZA виготовляє на власному виробництві у Львові — їх можна переглянути в <a href=\"/fiksatory-armatury\" data-go=\"catalog\" data-a=\"rebar\">каталозі фіксаторів арматури</a>."], ["h2", "Навіщо потрібні пластикові фіксатори"], ["p", "Основне завдання фіксатора — забезпечити проєктну товщину захисного шару бетону, тобто відстань від поверхні конструкції до найближчого стрижня. Від неї залежить, наскільки надійно бетон захищатиме сталь від вологи, корозії та вогню. Докладно про це ми розповідаємо в статті <a href=\"/blog/zakhysnyi-shar-betonu\" data-go=\"post\" data-a=\"2\">«Захисний шар бетону: норми і як його забезпечити»</a>."], ["p", "Друге завдання — зберегти геометрію каркаса під час робіт. Арматурна сітка на перекритті витримує вагу людей, тачок, рукава бетононасоса; стіни й колони зазнають тиску свіжої бетонної суміші. Фіксатори розподіляють ці навантаження й не дають стрижням зміщуватися."], ["p", "Чому саме пластик, а не уламки цегли, бруски чи обрізки арматури, які досі трапляються на будмайданчиках:"], ["ul", "<li>пластиковий фіксатор має точну висоту, задану пресформою, — без «на око»;</li><li>він не вбирає воду й не створює в бетоні каналу, по якому волога дістанеться до арматури;</li><li>не іржавіє і не стає «містком» корозії, як металеві підкладки;</li><li>встановлюється за секунди, а ажурна форма дозволяє бетону щільно обтікати виріб.</li>"], ["blockquote", "<p>Фіксатор коштує в сотні разів менше, ніж ремонт конструкції, у якій арматура опинилася біля самої поверхні. Тому економити на кількості фіксаторів — найдорожча економія на об’єкті.</p>"], ["h2", "Від чого залежить вибір фіксатора"], ["p", "Перш ніж обирати конкретну модель, дайте відповідь на кілька запитань. Вони одразу звужують вибір до одного-двох варіантів:"], ["ul", "<li><b>Яка основа?</b> Сипка (ґрунт, пісок, щебінь, гідроізоляційна плівка) чи тверда (бетонна підготовка, плита, опалубка).</li><li><b>Як розташована арматура?</b> Горизонтально — у плитах, стяжках, підлогах; вертикально — у стінах, колонах, пілонах.</li><li><b>Який проєктний захисний шар?</b> Його беруть із креслень: 15, 20, 25, 30, 40, 50 мм і більше.</li><li><b>Який діаметр стрижнів?</b> Це важливо для фіксаторів, що надягаються на стрижень або защіпаються на нього.</li><li><b>Яке навантаження?</b> Важкий каркас фундаментної плити й легка сітка стяжки потребують різної опори.</li>"], ["h2", "Фіксатори для горизонтальної арматури"], ["h3", "«Настил» — для ґрунту, піску, щебеню й плівки"], ["p", "<a href=\"/fiksator-nastyl\" data-go=\"product\" data-a=\"1-0\">Фіксатор «Настил»</a> створений для сипкої та м’якої основи. Його головна особливість — збільшена площа опори: виріб не продавлює пісок чи утеплювач і не рве гідроізоляційну мембрану. Саме його обирають для фундаментних плит, плит на ґрунті, підлог по підготовці зі щебеню. Доступні висоти — від 25–30 до 90–100 мм, тож «Настил» закриває і звичайні, і збільшені захисні шари фундаментів."], ["h3", "«Стійка» — для плит і підлог на твердій основі"], ["p", "<a href=\"/fiksator-stiika\" data-go=\"product\" data-a=\"2-0\">Фіксатор «Стійка»</a> тримає горизонтальну арматуру на бетонній або іншій твердій поверхні: у плитах перекриття, стяжках, промислових підлогах. Конструкція рівномірно розподіляє вагу каркаса. Частина типорозмірів багаторівнева — наприклад, 20-25-30: один виріб дає три висоти залежно від того, як його поставити. Це зручно, коли на об’єкті потрібні різні захисні шари."], ["h3", "«Защіпка» і «Засувка» — фіксація на стрижні"], ["p", "<a href=\"/fiksator-zashchipka\" data-go=\"product\" data-a=\"4-0\">«Защіпка»</a> защіпається на арматуру й утримує її на твердій основі; типорозміри 15/10, 20/10 і 25/10, де перше число — висота захисного шару в міліметрах. <a href=\"/fiksator-zasuvka\" data-go=\"product\" data-a=\"5-0\">«Засувка»</a> розрахована на більші навантаження й діаметри: розмір 50/8-24 означає захисний шар 50 мм для стрижнів від 8 до 24 мм. Такі фіксатори не зсуваються зі свого місця, навіть коли по сітці активно ходять."], ["cta", "{\"t\": \"Не знаєте, який фіксатор підійде?\", \"d\": \"Надішліть креслення або специфікацію — підберемо модель, висоту й кількість під ваш проєкт.\", \"b\": [[\"Каталог фіксаторів\", \"cat_rebar\", \"catalog\", \"rebar\", \"/fiksatory-armatury\"], [\"Запросити розрахунок\", \"rfq\"]]}"], ["h2", "Фіксатори для вертикальних конструкцій"], ["h3", "«Зірочка» — для стін, колон і пілонів"], ["p", "<a href=\"/fiksator-zirochka\" data-go=\"product\" data-a=\"3-0\">Фіксатор «Зірочка»</a> надягається на вертикальний стрижень і впирається в щит опалубки по колу, тому захисний шар однаковий з будь-якого боку. Під час монтажу опалубки «колесо» прокочується по щиту, не чіпляючись за нього. Розміри від 15/6-12 до 50/12-20: перше число — захисний шар, далі — діапазон діаметрів арматури. Еластичний замок надійно тримається на стрижнях різної товщини."], ["p", "«Зірочку» також використовують у кутах і на бічних гранях горизонтальних каркасів — скрізь, де арматура має триматися на відстані від вертикальної опалубки."], ["h2", "Як підібрати висоту фіксатора"], ["p", "Висота фіксатора — це не «приблизно», а конкретне значення з проєкту. Діяти варто в такому порядку:"], ["ol", "<li>Знайдіть у кресленнях проєктну товщину захисного шару для кожного елемента: фундаменту, перекриття, стін.</li><li>Пам’ятайте, що шар відраховують від поверхні бетону до найближчого стрижня — часто це хомут або поперечна арматура, а не робочий стрижень.</li><li>Підберіть фіксатор, висота якого дорівнює цьому значенню. Якщо точного розміру немає, беріть найближчий більший, але не менший.</li><li>Для «Зірочки» й «Засувки» перевірте, чи входить діаметр вашої арматури в діапазон виробу.</li><li>Для верхньої сітки плити фіксатори захисного шару не підходять — її тримають окремі підставки або каркаси, розраховані на висоту між сітками.</li>"], ["h2", "Скільки фіксаторів потрібно на 1 м²"], ["p", "Для горизонтальної арматури орієнтовна витрата — 4–6 шт. на м². Що тонші стрижні й що більший крок сітки, то частіше ставлять фіксатори: тонка арматура прогинається між опорами. Для масивних каркасів із великим діаметром стрижнів крок можна збільшити."], ["p", "Для стін і колон «Зірочки» розставляють у шаховому порядку, приблизно через кожен метр по висоті й довжині, з кожного боку стіни. Обов’язково — біля країв, отворів і в місцях з’єднання каркасів."], ["p", "Приклад розрахунку: фундаментна плита площею 120 м², витрата 5 шт./м² — це 600 фіксаторів «Настил». Додайте запас 5–10 % на підрізку й втрати — і отримаєте 650–660 шт. Фіксатори PLASTIZA постачаються упаковками від 100 до 2000 шт., точне фасування вказане в картці кожного товару."], ["h2", "Типові помилки під час вибору та монтажу"], ["ul", "<li>Ставлять «Стійку» на пісок або утеплювач — фіксатор продавлює основу, і шар зменшується.</li><li>Обирають висоту «трохи меншу», бо потрібної немає на складі, — і закладають дефект у конструкцію.</li><li>Економлять на кількості: між рідкими опорами сітка прогинається під ногами.</li><li>Підбирають «Зірочку» не під той діаметр — вона сповзає або не надягається.</li><li>Не перевіряють каркас перед бетонуванням. Кілька хвилин з рулеткою вберігають від місяців ремонту.</li>"], ["h2", "Часті питання"], ["h3", "Чи можна використовувати один фіксатор для різних висот?"], ["p", "Так, частина моделей «Стійка» багаторівнева: залежно від положення виробу він дає дві або три висоти. Це зменшує кількість позицій у замовленні."], ["h3", "Чи витримують пластикові фіксатори вагу людей і бетону?"], ["p", "Так, якщо їх правильно підібрано й розставлено з потрібним кроком. Фіксатори розраховані на тиск арматурного каркаса та ходіння по сітці під час робіт."], ["h3", "Чи не стає фіксатор слабким місцем у бетоні?"], ["p", "Ні. Його переріз малий порівняно з конструкцією, а ажурна форма дає бетону щільно заповнити простір навколо. Пластик не вбирає воду й не іржавіє, тому не створює шляху для корозії."], ["h2", "Висновок"], ["p", "Правильний фіксатор арматури підбирають за трьома параметрами: основа, положення стрижнів і проєктний захисний шар. «Настил» — для сипкої основи, «Стійка», «Защіпка» й «Засувка» — для твердої, «Зірочка» — для вертикальних елементів. Якщо сумніваєтеся, надішліть нам специфікацію: менеджер підбере моделі, розрахує кількість і запропонує доставку зі складу у Львові або Києві — <a href=\"/dostavka\" data-go=\"delivery\">умови доставки</a>."]], [["p", "A rebar spacer is a small plastic part that decides whether reinforcement ends up where the designer put it. Spacers hold the cage at the specified height while workers walk on it, while concrete is pumped in and while it is compacted with a poker vibrator. If the cage sinks even a few millimetres, the structure loses part of its concrete cover — and part of its service life."], ["p", "There are dozens of shapes and sizes on the market, which causes confusion: what to buy for a raft on a sand bed, for a slab on decking or for a basement wall. This article explains how to choose a rebar spacer by base and element type, how to match its height to the design cover and how to work out the quantity for a site. Every product mentioned is made by PLASTIZA at our own plant in Lviv — see the <a href=\"/en/rebar-spacers\" data-go=\"catalog\" data-a=\"rebar\">rebar spacer catalog</a>."], ["h2", "Why plastic spacers are used"], ["p", "The main job of a spacer is to provide the design concrete cover — the distance from the surface of the element to the nearest bar. It determines how well concrete protects steel from moisture, corrosion and fire. We cover this in detail in <a href=\"/en/blog/concrete-cover\" data-go=\"post\" data-a=\"2\">“Concrete cover: requirements and how to achieve it”</a>."], ["p", "The second job is to keep the cage geometry during works. A slab mesh carries people, barrows and the pump hose; walls and columns take the pressure of fresh concrete. Spacers spread these loads and stop the bars from moving."], ["p", "Why plastic rather than broken bricks, timber offcuts or rebar scraps that still appear on sites:"], ["ul", "<li>a plastic spacer has an exact height set by the mold — no guesswork;</li><li>it does not absorb water or create a channel for moisture to reach the steel;</li><li>it does not rust or form a corrosion bridge like metal chairs;</li><li>it installs in seconds, and its open shape lets concrete flow tightly around it.</li>"], ["blockquote", "<p>A spacer costs hundreds of times less than repairing an element whose rebar ended up next to the surface. Saving on the number of spacers is the most expensive saving on site.</p>"], ["h2", "What the choice depends on"], ["p", "Answer a few questions first — they narrow the choice to one or two models:"], ["ul", "<li><b>What is the base?</b> Loose (soil, sand, gravel, membrane) or firm (blinding concrete, slab, formwork).</li><li><b>How is the rebar positioned?</b> Horizontally — slabs, screeds, floors; vertically — walls, columns, piers.</li><li><b>What is the design cover?</b> Taken from the drawings: 15, 20, 25, 30, 40, 50 mm or more.</li><li><b>What bar diameter?</b> Important for spacers that clip onto or slide over the bar.</li><li><b>What load?</b> A heavy raft cage and a light screed mesh need different support.</li>"], ["h2", "Spacers for horizontal rebar"], ["h3", "“Nastil” — for soil, sand, gravel and membranes"], ["p", "The <a href=\"/en/slab-chair-nastil\" data-go=\"product\" data-a=\"1-0\">“Nastil” slab chair</a> is designed for loose and soft bases. Its wide footprint does not punch into sand or insulation and does not tear waterproofing membranes. It is the usual choice for raft foundations, slabs on grade and floors on a gravel bed. Heights range from 25–30 to 90–100 mm, covering both standard and increased foundation covers."], ["h3", "“Stiika” — for slabs and floors on a firm base"], ["p", "The <a href=\"/en/rebar-chair-stiika\" data-go=\"product\" data-a=\"2-0\">“Stiika” chair</a> holds horizontal rebar on concrete or another firm surface: floor slabs, screeds, industrial floors. It spreads the weight of the cage evenly. Some sizes are multi-level — for example 20-25-30: one part gives three heights depending on how it is placed, which is handy when a site needs several covers."], ["h3", "“Zashchipka” and “Zasuvka” — clip-on spacers"], ["p", "<a href=\"/en/clip-spacer-zashchipka\" data-go=\"product\" data-a=\"4-0\">“Zashchipka”</a> clips onto the bar and holds it on a firm base; sizes 15/10, 20/10 and 25/10, where the first number is the cover in millimetres. <a href=\"/en/slide-spacer-zasuvka\" data-go=\"product\" data-a=\"5-0\">“Zasuvka”</a> is designed for heavier loads and diameters: size 50/8-24 means 50 mm cover for bars from 8 to 24 mm. These spacers stay in place even with heavy foot traffic on the mesh."], ["cta", "{\"t\": \"Not sure which spacer fits?\", \"d\": \"Send us a drawing or schedule — we will pick the model, height and quantity for your project.\", \"b\": [[\"Rebar spacers\", \"cat_rebar\", \"catalog\", \"rebar\", \"/en/rebar-spacers\"], [\"Request a quote\", \"rfq\"]]}"], ["h2", "Spacers for vertical elements"], ["h3", "“Zirochka” — for walls, columns and piers"], ["p", "The <a href=\"/en/star-spacer-zirochka\" data-go=\"product\" data-a=\"3-0\">“Zirochka” wheel spacer</a> clips onto a vertical bar and bears against the formwork all around, so the cover is equal on every side. When the formwork is closed, the wheel rolls along the panel instead of snagging. Sizes run from 15/6-12 to 50/12-20: the first number is the cover, then the range of bar diameters. The flexible lock holds firmly on bars of different thickness."], ["p", "“Zirochka” is also used at corners and side faces of horizontal cages — anywhere rebar must stay clear of vertical formwork."], ["h2", "How to choose the spacer height"], ["p", "Spacer height is not “roughly” — it is a specific value from the design:"], ["ol", "<li>Find the design cover for each element in the drawings: foundation, slab, walls.</li><li>Remember that cover is measured to the nearest bar — often a link or distribution bar, not the main bar.</li><li>Choose a spacer equal to that value. If the exact size is unavailable, go up, never down.</li><li>For “Zirochka” and “Zasuvka”, check that your bar diameter is within the part’s range.</li><li>Cover spacers are not for the top mesh of a slab — it needs separate supports sized to the distance between meshes.</li>"], ["h2", "How many spacers per m²"], ["p", "For horizontal rebar, allow roughly 4–6 pcs per m². The thinner the bars and the wider the mesh, the closer the spacing — thin bars sag between supports. Heavy cages with large bars allow wider spacing."], ["p", "For walls and columns, place “Zirochka” spacers in a staggered pattern about every metre in height and length, on each face — and always near edges, openings and cage joints."], ["p", "Example: a 120 m² raft at 5 pcs/m² needs 600 “Nastil” spacers. Add 5–10 % for waste and you get 650–660 pcs. PLASTIZA spacers come in packs of 100 to 2,000 pcs; the exact pack size is shown on each product page."], ["h2", "Common mistakes"], ["ul", "<li>Using “Stiika” on sand or insulation — it punches into the base and the cover shrinks.</li><li>Choosing a slightly lower height because the right one is out of stock — building a defect into the structure.</li><li>Saving on quantity — the mesh sags underfoot between sparse supports.</li><li>Picking a “Zirochka” for the wrong diameter — it slides off or does not fit.</li><li>Skipping the pre-pour check. A few minutes with a tape measure save months of repairs.</li>"], ["h2", "FAQ"], ["h3", "Can one spacer serve several heights?"], ["p", "Yes, some “Stiika” models are multi-level and give two or three heights depending on orientation, which reduces the number of line items."], ["h3", "Can plastic spacers carry people and concrete?"], ["p", "Yes, when correctly chosen and spaced. They are designed for the weight of the cage and foot traffic during works."], ["h3", "Does a spacer become a weak point in concrete?"], ["p", "No. Its cross-section is tiny compared to the element, and its open shape lets concrete fill the space around it. Plastic does not absorb water or rust, so it creates no corrosion path."], ["h2", "Conclusion"], ["p", "The right rebar spacer depends on three things: the base, the bar position and the design cover. “Nastil” for loose bases; “Stiika”, “Zashchipka” and “Zasuvka” for firm ones; “Zirochka” for vertical elements. If in doubt, send us your schedule: we will pick the models, calculate quantities and ship from our Lviv or Kyiv warehouse — see <a href=\"/en/delivery\" data-go=\"delivery\">delivery options</a>."]]], "tag": ["Поради", "Guides"]}, {"id": 2, "st": "pub", "date": "2026-10-02", "t": ["Захисний шар бетону: що це, норми та як його забезпечити на об’єкті", "Concrete cover: what it is, typical values and how to achieve it on site"], "e": ["Що таке захисний шар бетону, від чого залежить його товщина, чим загрожують помилки і як пластикові фіксатори допомагають витримати проєктне значення.", "What concrete cover is, what determines its thickness, what goes wrong when it is too thin or too thick, and how plastic spacers help you hit the design value."], "b": [[["p", "Захисний шар бетону — один із тих параметрів, які непомітні в готовій будівлі, але визначають, скільки вона прослужить. Це відстань від поверхні бетону до найближчої арматури. Кілька міліметрів різниці здаються дрібницею під час бетонування, а через роки перетворюються на іржаві патьоки, тріщини й відшарування бетону."], ["p", "У цій статті пояснюємо, навіщо потрібен захисний шар, від чого залежить його товщина, які орієнтовні значення використовують для типових конструкцій, що відбувається, коли шар порушено, і як забезпечити його на будмайданчику за допомогою <a href=\"/fiksatory-armatury\" data-go=\"catalog\" data-a=\"rebar\">фіксаторів арматури</a>."], ["h2", "Що таке захисний шар бетону"], ["p", "Захисний шар — це товщина бетону між зовнішньою поверхнею конструкції та поверхнею найближчого арматурного стрижня. Важливо: найближчим часто є не робоча арматура, а хомути, поперечні стрижні чи монтажні елементи. Саме до них і ведуть відлік."], ["p", "У проєкті зазвичай вказують номінальне значення — те, яке потрібно витримати під час монтажу. Воно вже містить запас на неминучі відхилення при виготовленні каркаса."], ["h2", "Навіщо потрібен захисний шар"], ["p", "Бетон — це не лише «обгортка» для арматури. Він виконує кілька функцій одночасно:"], ["ul", "<li><b>Захист від корозії.</b> Свіжий бетон має сильно лужне середовище, у якому сталь вкривається пасивною плівкою й не іржавіє. З роками вуглекислий газ із повітря поступово нейтралізує бетон від поверхні вглиб — це карбонізація. Поки фронт карбонізації не дійшов до арматури, вона захищена.</li><li><b>Вогнестійкість.</b> Під час пожежі бетон уповільнює нагрівання сталі. Тонкий шар — це швидша втрата міцності арматури.</li><li><b>Спільна робота бетону й арматури.</b> Для зчеплення та анкерування стрижень має бути повністю оточений бетоном достатньої товщини.</li><li><b>Довговічність загалом.</b> Волога, солі, агресивні ґрунтові води — усе це має пройти крізь захисний шар, перш ніж дістанеться до металу.</li>"], ["blockquote", "<p>Арматура в бетоні не іржавіє доти, доки її захищає лужне середовище. Захисний шар — це запас часу, за який агресивні чинники мають пройти шлях до сталі.</p>"], ["h2", "Від чого залежить товщина захисного шару"], ["p", "Мінімальну й номінальну товщину визначає проєктувальник на підставі норм — в Україні це, зокрема, ДБН В.2.6-98:2009 «Бетонні та залізобетонні конструкції» та ДСТУ Б В.2.6-156:2010, у європейській практиці — EN 1992-1-1 (Єврокод 2). Основні чинники:"], ["ul", "<li><b>Умови експлуатації.</b> Сухе приміщення, вулиця, контакт із ґрунтом, вода, солі — що агресивніше середовище, то товщий шар.</li><li><b>Тип конструкції.</b> Плити, балки, колони, фундаменти мають різні вимоги.</li><li><b>Діаметр арматури.</b> Шар не може бути меншим за діаметр стрижня.</li><li><b>Вимоги до вогнестійкості.</b> Для конструкцій із нормованою межею вогнестійкості шар збільшують.</li><li><b>Наявність підготовки під фундамент.</b> Бетонування прямо на ґрунт вимагає значно більшого шару.</li>"], ["h3", "Орієнтовні значення для типових конструкцій"], ["p", "Щоб зорієнтуватися в порядку цифр, наведемо значення, які найчастіше трапляються в проєктах житлових і громадських будівель:"], ["ul", "<li>плити перекриття та внутрішні стіни в сухих приміщеннях — близько 15–25 мм;</li><li>балки, ригелі та колони — близько 20–30 мм;</li><li>конструкції на відкритому повітрі та у вологих умовах — 30–40 мм і більше;</li><li>фундаменти з бетонною підготовкою — від 35–40 мм;</li><li>фундаменти, які бетонують безпосередньо на ґрунт, без підготовки, — від 70 мм.</li>"], ["p", "Це лише орієнтир для розуміння. Для конкретного об’єкта значення завжди беруть із проєкту: саме воно враховує клас бетону, середовище й вимоги до вогнестійкості."], ["h2", "Чим загрожує порушення захисного шару"], ["h3", "Занадто тонкий шар"], ["p", "Карбонізація й волога швидше доходять до сталі. Арматура починає іржавіти, а продукти корозії займають у кілька разів більший об’єм, ніж метал. Вони розпирають бетон зсередини: з’являються тріщини вздовж стрижнів, рудий наліт, згодом — відколи й оголена арматура. Окрім того, знижується вогнестійкість і погіршується анкерування стрижнів."], ["h3", "Занадто товстий шар"], ["p", "Перебір теж шкодить. Якщо нижня арматура плити піднялася вище за проєкт, зменшується робоча висота перерізу — і несна здатність падає. Товстий шар без армування схильний до тріщиноутворення, а конструкція стає важчою, ніж розраховано."], ["h2", "Чому захисний шар порушується на будмайданчику"], ["p", "Більшість проблем виникає не в проєкті, а під час монтажу:"], ["ul", "<li>каркас кладуть на уламки цегли, дерев’яні бруски чи камені — висота довільна, а дерево ще й вбирає воду;</li><li>фіксаторів ставлять занадто мало, і сітка прогинається під вагою людей;</li><li>фіксатори обирають «приблизно» за висотою;</li><li>на сипкій основі використовують опори з малою площею — вони тонуть у піску;</li><li>під час вібрування й подачі бетону каркас зміщується, бо не закріплений.</li>"], ["h2", "Як забезпечити проєктний захисний шар"], ["p", "Надійний спосіб — пластикові фіксатори заводського виготовлення, підібрані під конкретний елемент. Порядок дій:"], ["ol", "<li>Візьміть із проєкту значення захисного шару для кожного типу конструкцій.</li><li>Підберіть тип фіксатора під основу й положення арматури: <a href=\"/fiksator-nastyl\" data-go=\"product\" data-a=\"1-0\">«Настил»</a> — для ґрунту, піску та плівки; <a href=\"/fiksator-stiika\" data-go=\"product\" data-a=\"2-0\">«Стійка»</a> і <a href=\"/fiksator-zashchipka\" data-go=\"product\" data-a=\"4-0\">«Защіпка»</a> — для твердої основи; <a href=\"/fiksator-zirochka\" data-go=\"product\" data-a=\"3-0\">«Зірочка»</a> — для стін і колон.</li><li>Підберіть висоту, що точно відповідає проєктному шару.</li><li>Розставте фіксатори з потрібним кроком — для горизонтальної арматури в середньому 4–6 шт. на м². Як порахувати точніше, розповідаємо в статті <a href=\"/blog/yak-obraty-fiksator-armatury\" data-go=\"post\" data-a=\"1\">«Як обрати фіксатор арматури»</a>.</li><li>Перед бетонуванням перевірте каркас: виміряйте відстань до опалубки й основи в кількох точках, особливо біля країв і отворів.</li>"], ["cta", "{\"t\": \"Потрібні фіксатори під ваш проєктний шар?\", \"d\": \"Підберемо модель і висоту для кожного елемента та порахуємо кількість на об’єкт.\", \"b\": [[\"Фіксатори арматури\", \"cat_rebar\", \"catalog\", \"rebar\", \"/fiksatory-armatury\"], [\"Обговорити замовлення\", \"rfq\"]]}"], ["h2", "Як перевірити захисний шар"], ["p", "До бетонування шар контролюють рулеткою або шаблоном — це найпростіше й найдешевше. Після бетонування його можна перевірити неруйнівним методом: магнітні прилади (вимірювачі захисного шару) визначають відстань до арматури крізь бетон. Таку перевірку проводять під час приймання робіт або обстеження будівель."], ["h2", "Часті питання"], ["h3", "Чи можна виправити тонкий захисний шар після бетонування?"], ["p", "Частково — ремонтними складами, торкретуванням, захисними покриттями. Але це дорожче й менш надійно, ніж правильно встановити фіксатори до заливання."], ["h3", "Чи враховують фіксатори в захисному шарі?"], ["p", "Фіксатор лише утримує арматуру на потрібній відстані. Його висота має дорівнювати проєктному шару, а сам виріб залишається в бетоні й не впливає на довговічність."], ["h3", "Скільки коштує забезпечити захисний шар?"], ["p", "Вартість фіксаторів для типової плити — незначна частка кошторису бетонних робіт. Точну суму розрахуємо за вашою специфікацією."], ["h2", "Висновок"], ["p", "Захисний шар бетону — це гарантія того, що арматура працюватиме десятиліттями. Його значення задає проєкт, а витримати його на об’єкті допомагають правильно підібрані фіксатори. Якщо потрібна консультація щодо вибору або розрахунок кількості — залиште заявку нижче, і менеджер PLASTIZA зв’яжеться з вами."]], [["p", "Concrete cover is one of those parameters you cannot see in a finished building, yet it decides how long the building lasts. It is the distance from the concrete surface to the nearest reinforcement. A few millimetres seem trivial during the pour, but years later they turn into rust stains, cracks and spalling."], ["p", "This article explains why cover matters, what determines its thickness, which values are typical for common elements, what happens when it is wrong and how to achieve it on site with <a href=\"/en/rebar-spacers\" data-go=\"catalog\" data-a=\"rebar\">rebar spacers</a>."], ["h2", "What concrete cover is"], ["p", "Cover is the thickness of concrete between the outer face of an element and the surface of the nearest bar. The nearest bar is often a link, stirrup or distribution bar rather than the main reinforcement — and cover is measured to it."], ["p", "Drawings usually state the nominal cover: the value to achieve during fixing. It already includes an allowance for unavoidable deviations."], ["h2", "Why cover matters"], ["ul", "<li><b>Corrosion protection.</b> Fresh concrete is highly alkaline, so steel forms a passive film and does not rust. Over the years carbon dioxide neutralises concrete from the surface inwards — carbonation. Until the carbonation front reaches the steel, the bars are protected.</li><li><b>Fire resistance.</b> In a fire, concrete slows the heating of steel. A thin cover means faster loss of strength.</li><li><b>Bond and anchorage.</b> Bars must be fully surrounded by enough concrete to work together with it.</li><li><b>Durability in general.</b> Moisture, salts and aggressive groundwater must pass through the cover before reaching the metal.</li>"], ["blockquote", "<p>Rebar in concrete does not rust while the alkaline environment protects it. Cover is the time it takes aggressive agents to travel to the steel.</p>"], ["h2", "What determines cover thickness"], ["p", "Minimum and nominal values are set by the designer under the applicable codes — in Ukraine, DBN V.2.6-98:2009 and DSTU B V.2.6-156:2010; in European practice, EN 1992-1-1 (Eurocode 2). Key factors:"], ["ul", "<li><b>Exposure conditions:</b> dry interior, outdoors, contact with soil, water or salts.</li><li><b>Element type:</b> slabs, beams, columns and foundations differ.</li><li><b>Bar diameter:</b> cover may not be less than the bar diameter.</li><li><b>Fire resistance requirements.</b></li><li><b>Blinding under foundations:</b> casting directly against soil needs much more cover.</li>"], ["h3", "Typical values for common elements"], ["p", "To give a sense of scale, these values are often seen in residential and public buildings:"], ["ul", "<li>floor slabs and internal walls in dry rooms — about 15–25 mm;</li><li>beams and columns — about 20–30 mm;</li><li>outdoor and wet elements — 30–40 mm or more;</li><li>foundations on blinding — from 35–40 mm;</li><li>foundations cast directly against soil — from 70 mm.</li>"], ["p", "These are orientation figures only. For a real project, always take the value from the design."], ["h2", "What goes wrong"], ["h3", "Cover too thin"], ["p", "Carbonation and moisture reach the steel sooner. Rust occupies several times the volume of the metal and bursts the concrete from inside: cracks along the bars, rust stains, later spalling and exposed rebar. Fire resistance and anchorage also suffer."], ["h3", "Cover too thick"], ["p", "If the bottom rebar of a slab sits higher than designed, the effective depth falls — and so does load capacity. Thick unreinforced cover is prone to cracking and adds weight."], ["h2", "Why cover fails on site"], ["ul", "<li>cages are laid on bricks, timber or stones — random heights, and timber absorbs water;</li><li>too few spacers, so the mesh sags under foot traffic;</li><li>spacer heights chosen “roughly”;</li><li>small-footprint supports used on loose bases sink into sand;</li><li>the cage moves during vibration and pumping because it is not secured.</li>"], ["h2", "How to achieve the design cover"], ["ol", "<li>Take the cover for each element type from the drawings.</li><li>Choose the spacer type for the base and bar position: <a href=\"/en/slab-chair-nastil\" data-go=\"product\" data-a=\"1-0\">“Nastil”</a> for soil, sand and membranes; <a href=\"/en/rebar-chair-stiika\" data-go=\"product\" data-a=\"2-0\">“Stiika”</a> and <a href=\"/en/clip-spacer-zashchipka\" data-go=\"product\" data-a=\"4-0\">“Zashchipka”</a> for firm bases; <a href=\"/en/star-spacer-zirochka\" data-go=\"product\" data-a=\"3-0\">“Zirochka”</a> for walls and columns.</li><li>Choose the height that exactly matches the design cover.</li><li>Space them correctly — on average 4–6 pcs per m² for horizontal rebar. See <a href=\"/en/blog/how-to-choose-rebar-spacer\" data-go=\"post\" data-a=\"1\">“How to choose a rebar spacer”</a> for details.</li><li>Check the cage before pouring at several points, especially near edges and openings.</li>"], ["cta", "{\"t\": \"Need spacers for your design cover?\", \"d\": \"We will pick the model and height for each element and calculate quantities for the site.\", \"b\": [[\"Rebar spacers\", \"cat_rebar\", \"catalog\", \"rebar\", \"/en/rebar-spacers\"], [\"Discuss an order\", \"rfq\"]]}"], ["h2", "How to check cover"], ["p", "Before the pour, use a tape measure or template — the cheapest check. After the pour, magnetic cover meters measure the distance to rebar through concrete without damage; they are used at handover and in building surveys."], ["h2", "FAQ"], ["h3", "Can thin cover be fixed after pouring?"], ["p", "Partly — with repair mortars, sprayed concrete or protective coatings. It is costlier and less reliable than fitting spacers correctly before the pour."], ["h3", "Is the spacer part of the cover?"], ["p", "The spacer only holds the bar at the right distance. Its height equals the design cover; it stays in the concrete and does not affect durability."], ["h3", "How much does it cost to ensure cover?"], ["p", "Spacers for a typical slab are a tiny share of the concrete works budget. We will price your schedule exactly."], ["h2", "Conclusion"], ["p", "Concrete cover is what lets rebar work for decades. The design sets the value; correctly chosen spacers let you achieve it on site. For advice or a quantity estimate, leave a request below and a PLASTIZA manager will contact you."]]], "tag": ["Будівництво", "Construction"]}, {"id": 3, "st": "pub", "date": "2026-09-18", "t": ["Лиття пластмас під тиском: етапи від креслення до серійної партії", "Plastic injection molding: stages from drawing to production run"], "e": ["Як працює лиття пластику під тиском, які матеріали використовують, з яких етапів складається запуск виробу і від чого залежить ціна деталі.", "How plastic injection molding works, which materials are used, what stages a new part goes through and what drives the unit price."], "b": [[["p", "Лиття під тиском — основна технологія, за якою виготовляють більшість пластикових деталей навколо нас: від корпусів побутової техніки до будівельних фіксаторів. Вона дозволяє випускати тисячі однакових виробів зі стабільною геометрією та за прогнозовану ціну."], ["p", "Але між ідеєю й першою серійною партією лежить кілька етапів: аналіз креслення, проєктування й виготовлення пресформи, пробне лиття, доведення і лише потім — серія. У цій статті розповідаємо, як проходить цей шлях на виробництві PLASTIZA у Львові, на що звернути увагу замовнику і як зекономити час і бюджет. Детальніше про послугу — на сторінці <a href=\"/lyttia-plastyku\" data-go=\"soon\" data-a=\"0\">«Лиття пластикових виробів»</a>."], ["h2", "Що таке лиття пластмас під тиском"], ["p", "Сировину — полімерні гранули — подають у матеріальний циліндр термопластавтомата (ТПА). Там вона нагрівається й пластифікується шнеком. Далі розплав під високим тиском впорскується в закриту пресформу, заповнює порожнину та охолоджується. Пресформа розкривається, виштовхувачі знімають готовий виріб, і цикл повторюється."], ["p", "Тривалість одного циклу — від кількох секунд до хвилини й більше. Вона залежить від товщини стінок, матеріалу та кількості гнізд у формі. Саме час циклу — один із головних чинників собівартості деталі."], ["h2", "Переваги технології"], ["ul", "<li><b>Повторюваність.</b> Кожен виріб у партії має однакову геометрію, задану пресформою.</li><li><b>Складна форма.</b> Ребра жорсткості, отвори, защіпки, різьби — усе формується за один цикл.</li><li><b>Низька ціна деталі на великих тиражах.</b> Витрати на пресформу розподіляються на весь обсяг випуску.</li><li><b>Мінімум відходів.</b> Ливники й брак переробляють і повторно використовують там, де це дозволяють вимоги до виробу.</li><li><b>Широкий вибір матеріалів</b> — від м’яких до конструкційних пластиків.</li>"], ["h2", "Які матеріали використовують"], ["p", "Матеріал обирають під умови роботи виробу: навантаження, температуру, контакт із хімією, ультрафіолетом чи вологою. Найпоширеніші:"], ["ul", "<li><b>Поліпропілен (PP)</b> — легкий, хімічно стійкий, добре підходить для технічних і будівельних виробів;</li><li><b>Поліетилен (PE)</b> — еластичний, стійкий до вологи та низьких температур;</li><li><b>ABS</b> — жорсткий, з гарною поверхнею, для корпусів і декоративних деталей;</li><li><b>Поліамід (PA)</b> — міцний і зносостійкий, для навантажених механічних деталей;</li><li><b>Полікарбонат (PC) і POM</b> — для точних деталей і підвищених вимог до міцності.</li>"], ["p", "До базового полімеру додають барвники, УФ-стабілізатори, наповнювачі. Склад погоджуємо із замовником на етапі технічного завдання."], ["h2", "Етапи: від креслення до серійної партії"], ["h3", "1. Аналіз креслення і технологічності"], ["p", "Інженер перевіряє, чи можна виготовити деталь литтям без зайвих ускладнень. Ключові моменти: рівномірна товщина стінок, ухили для виймання з форми, радіуси замість гострих кутів, піднутрення, місце впорскування. На цьому етапі ми часто пропонуємо невеликі зміни конструкції, які спрощують пресформу й зменшують брак."], ["h3", "2. Проєктування та виготовлення пресформи"], ["p", "Пресформа — найдорожча й найвідповідальніша частина проєкту. Її проєктують у 3D, погоджують із замовником і виготовляють на верстатах із ЧПК. Про те, що підготувати до звернення і від чого залежить вартість, читайте в статті <a href=\"/blog/presforma-pid-vash-vyrib\" data-go=\"post\" data-a=\"4\">«Пресформа на замовлення: що підготувати»</a>, а про саму послугу — на сторінці <a href=\"/vyhotovlennia-presform\" data-go=\"soon\" data-a=\"1\">«Виготовлення пресформ»</a>."], ["h3", "3. Пробне лиття і доведення"], ["p", "Перші відливки показують, як форма працює в реальності. Технолог підбирає температуру, тиск, швидкість впорскування й час охолодження. За потреби форму доопрацьовують, щоб деталь відповідала кресленню."], ["h3", "4. Погодження зразків"], ["p", "Замовник отримує пробні вироби для перевірки розмірів, складання з іншими деталями та зовнішнього вигляду. Після погодження параметри процесу фіксуються."], ["h3", "5. Серійне виробництво і контроль якості"], ["p", "Серія йде на зафіксованих режимах. Розміри й вигляд виробів контролюють під час усього тиражу, щоб перша й остання деталь партії були однаковими."], ["blockquote", "<p>Найдешевше виправляти помилку на кресленні, дорожче — у металі пресформи, і найдорожче — у готовій партії. Тому ми приділяємо стільки уваги першому етапу.</p>"], ["cta", "{\"t\": \"Дослідіть наші напрями\", \"d\": \"Повний цикл в одних руках: від креслення та пресформи до серійної партії й доставки.\", \"b\": [[\"Лиття пластикових виробів\", \"srv0\", \"soon\", \"0\", \"/lyttia-plastyku\"], [\"Виготовлення пресформ\", \"srv1\", \"soon\", \"1\", \"/vyhotovlennia-presform\"], [\"Наше виробництво\", \"about\", \"about\", \"\", \"/vyrobnytstvo\"]]}"], ["h2", "Від чого залежить ціна пластикового виробу"], ["ul", "<li><b>Матеріал і маса деталі</b> — вартість сировини на кожен виріб.</li><li><b>Час циклу</b> — що довше охолоджується деталь, то дорожча машинна година на одиницю.</li><li><b>Кількість гнізд у пресформі</b> — багатогніздна форма дає більше деталей за цикл.</li><li><b>Вартість пресформи та тираж</b> — на великій серії частка форми в ціні мінімальна.</li><li><b>Додаткові операції</b> — складання, маркування, пакування.</li>"], ["h2", "Типові дефекти і як їх уникають"], ["ul", "<li><b>Недолив</b> — деталь заповнена не повністю; причина в недостатньому тиску, температурі чи вентиляції форми.</li><li><b>Облой</b> — тонкий «ласт» по лінії рознімання; виникає при зношеній формі або надмірному тиску.</li><li><b>Утяжини</b> — западини на товстих ділянках; лікуються рівномірною товщиною стінок і режимом підживлення.</li><li><b>Короблення</b> — деформація після виймання через нерівномірне охолодження.</li><li><b>Сліди потоку й лінії спаю</b> — видимі смуги на поверхні; залежать від розташування ливника.</li>"], ["p", "Більшість цих проблем закладається ще на етапі конструкції, тому аналіз технологічності — не формальність."], ["h2", "Обладнання та можливості PLASTIZA"], ["p", "Наше виробництво у Львові оснащене термопластавтоматами різного зусилля змикання, що дозволяє лити як дрібні фіксатори, так і великі технічні деталі. Ми працюємо як із власними пресформами, так і з формами замовника. Більше про парк обладнання — на сторінці <a href=\"/vyrobnytstvo\" data-go=\"about\">«Виробництво»</a>."], ["h2", "Часті питання"], ["h3", "Який мінімальний тираж?"], ["p", "Залежить від виробу та пресформи. Лиття під тиском вигідне від кількох тисяч деталей; для менших обсягів підкажемо, як оптимізувати конструкцію форми."], ["h3", "Чи можна лити вироби в моїй пресформі?"], ["p", "Так. Ми перевіримо стан форми, підберемо відповідний ТПА й режими та виготовимо партію. Також можемо передати вам пресформу, виготовлену під ваш виріб."], ["h3", "Скільки часу займає запуск?"], ["p", "Найбільше часу забирає виготовлення пресформи. Після її готовності пробне лиття й погодження зразків займає від кількох днів, а серію запускаємо відразу після погодження."], ["h2", "Висновок"], ["p", "Лиття під тиском — це точність, повторюваність і низька ціна деталі на тиражі. Успіх проєкту залежить від якісного креслення, продуманої пресформи й налаштованого процесу. Надішліть нам креслення, 3D-модель або зразок — підготуємо розрахунок вартості й термінів через форму нижче."]], [["p", "Injection molding is the main technology behind most plastic parts around us, from appliance housings to construction spacers. It produces thousands of identical parts with stable geometry at a predictable price."], ["p", "Between an idea and the first production batch lie several stages: drawing review, mold design and build, trial molding, fine-tuning and only then series production. Here is how that path looks at the PLASTIZA plant in Lviv, what customers should watch for and how to save time and budget. More about the service: <a href=\"/en/injection-molding\" data-go=\"soon\" data-a=\"0\">Plastic injection molding</a>."], ["h2", "What injection molding is"], ["p", "Polymer pellets are fed into the barrel of an injection molding machine, heated and plasticised by a screw. The melt is injected under high pressure into a closed mold, fills the cavity and cools. The mold opens, ejectors push the part out and the cycle repeats."], ["p", "A cycle takes from a few seconds to a minute or more, depending on wall thickness, material and the number of cavities. Cycle time is one of the main cost drivers."], ["h2", "Advantages"], ["ul", "<li><b>Repeatability</b> — every part in a batch has the geometry set by the mold.</li><li><b>Complex shapes</b> — ribs, holes, snap-fits and threads in one cycle.</li><li><b>Low unit cost at volume</b> — mold cost is spread across the run.</li><li><b>Little waste</b> — runners and rejects are reground where the specification allows.</li><li><b>Wide material choice</b> — from flexible to engineering plastics.</li>"], ["h2", "Materials"], ["ul", "<li><b>Polypropylene (PP)</b> — light and chemically resistant, good for technical and construction parts;</li><li><b>Polyethylene (PE)</b> — flexible, resistant to moisture and low temperatures;</li><li><b>ABS</b> — rigid with a good surface, for housings and visible parts;</li><li><b>Polyamide (PA)</b> — strong and wear-resistant for loaded parts;</li><li><b>Polycarbonate (PC) and POM</b> — for precise and demanding parts.</li>"], ["p", "Colourants, UV stabilisers and fillers are added as needed and agreed in the specification."], ["h2", "Stages: from drawing to production run"], ["h3", "1. Drawing and manufacturability review"], ["p", "An engineer checks wall thickness uniformity, draft angles, radii, undercuts and gate location. At this stage we often suggest small design changes that simplify the mold and reduce rejects."], ["h3", "2. Mold design and build"], ["p", "The mold is the most expensive and critical part of the project. It is designed in 3D, approved by the customer and machined on CNC equipment. See <a href=\"/en/blog/custom-mold-checklist\" data-go=\"post\" data-a=\"4\">“Custom mold: what to prepare”</a> and our <a href=\"/en/mold-making\" data-go=\"soon\" data-a=\"1\">mold making</a> service."], ["h3", "3. Trial molding and tuning"], ["p", "First shots show how the mold behaves. The process engineer sets temperature, pressure, injection speed and cooling time; the mold is adjusted if needed."], ["h3", "4. Sample approval"], ["p", "The customer checks sample dimensions, assembly and appearance. After approval, process parameters are locked."], ["h3", "5. Series production and quality control"], ["p", "The run uses the locked settings, with dimensions and appearance checked throughout so the first and last parts match."], ["blockquote", "<p>Fixing a mistake on the drawing is cheapest, in mold steel it costs more, and in a finished batch it costs the most. That is why we spend so much time on stage one.</p>"], ["cta", "{\"t\": \"Explore our services\", \"d\": \"Full cycle in one place: from drawing and mold to production batch and delivery.\", \"b\": [[\"Injection molding\", \"srv0\", \"soon\", \"0\", \"/en/injection-molding\"], [\"Mold making\", \"srv1\", \"soon\", \"1\", \"/en/mold-making\"], [\"Our production\", \"about\", \"about\", \"\", \"/en/production\"]]}"], ["h2", "What drives the unit price"], ["ul", "<li><b>Material and part weight.</b></li><li><b>Cycle time</b> — longer cooling means more machine time per part.</li><li><b>Number of cavities</b> — more parts per cycle.</li><li><b>Mold cost versus run size</b> — on large runs the mold share is minimal.</li><li><b>Secondary operations</b> — assembly, marking, packing.</li>"], ["h2", "Common defects and how to avoid them"], ["ul", "<li><b>Short shots</b> — incomplete fill from low pressure, temperature or poor venting.</li><li><b>Flash</b> — thin fins on the parting line from wear or excess pressure.</li><li><b>Sink marks</b> — dips over thick sections; fixed by uniform walls and packing pressure.</li><li><b>Warpage</b> — distortion from uneven cooling.</li><li><b>Flow and weld lines</b> — visible streaks depending on gate position.</li>"], ["p", "Most of these are designed in, so a manufacturability review is not a formality."], ["h2", "PLASTIZA capabilities"], ["p", "Our Lviv plant runs injection molding machines with a range of clamping forces, from small spacers to large technical parts. We work with our own molds and with customer molds. More on our equipment: <a href=\"/en/production\" data-go=\"about\">Production</a>."], ["h2", "FAQ"], ["h3", "What is the minimum run?"], ["p", "It depends on the part and the mold. Injection molding usually pays off from several thousand parts; for smaller volumes we will suggest how to optimise the mold."], ["h3", "Can you mold parts in my tool?"], ["p", "Yes. We will check the mold, choose a suitable machine and settings, and produce your batch. We can also hand over a mold made for your part."], ["h3", "How long does a launch take?"], ["p", "Mold making takes the most time. Once the mold is ready, trials and sample approval take from a few days, and series production starts right after approval."], ["h2", "Conclusion"], ["p", "Injection molding means precision, repeatability and low unit cost at volume. Success depends on a good drawing, a well-designed mold and a tuned process. Send us a drawing, 3D model or sample through the form below for a price and lead-time estimate."]]], "tag": ["Виробництво", "Production"]}, {"id": 4, "st": "pub", "date": "2026-09-05", "t": ["Виготовлення пресформи на замовлення: що підготувати, вартість і терміни", "Custom injection mold: what to prepare, cost drivers and lead times"], "e": ["Що потрібно виробнику для розрахунку пресформи, з чого вона складається, які чинники формують ціну й терміни і як скоротити шлях до першої партії.", "What a manufacturer needs to quote an injection mold, what a mold consists of, what drives cost and lead time and how to reach the first batch faster."], "b": [[["p", "Пресформа — це інструмент, який визначає якість кожної деталі, що з неї вийде. Помилки в конструкції форми важко й дорого виправити пізніше, тому підготовка до замовлення має не менше значення, ніж саме виготовлення."], ["p", "У цій статті пояснюємо, з чого складається пресформа для лиття пластику, що підготувати до першого звернення, від чого залежить вартість і терміни, а також як скоротити шлях до серійної партії. Детальніше про послугу — на сторінці <a href=\"/vyhotovlennia-presform\" data-go=\"soon\" data-a=\"1\">«Виготовлення пресформ»</a>."], ["h2", "З чого складається пресформа"], ["p", "Навіть проста на вигляд форма — це складний механізм із десятків деталей:"], ["ul", "<li><b>Формоутворні вставки (матриця й пуансон)</b> — створюють зовнішню й внутрішню поверхні виробу.</li><li><b>Ливникова система</b> — канали, якими розплав надходить у порожнину. Буває холодноканальною та гарячоканальною.</li><li><b>Система охолодження</b> — канали для теплоносія, від яких залежить час циклу та стабільність розмірів.</li><li><b>Система виштовхування</b> — штовхачі, плити, знімачі, що знімають деталь з пуансона.</li><li><b>Рухомі елементи</b> — повзуни, знаки, клини для піднутрень, отворів збоку, різьб.</li><li><b>Корпус (пакет плит)</b> — з’єднує всі вузли й встановлюється на термопластавтомат.</li>"], ["h2", "Що підготувати до звернення"], ["p", "Що більше даних ви надасте, то точнішою буде комерційна пропозиція. Ідеальний набір:"], ["ol", "<li><b>Креслення або 3D-модель</b> виробу — бажано у форматі STEP або IGES, плюс PDF із розмірами й допусками.</li><li><b>Матеріал</b> — марка пластику або хоча б умови роботи деталі: навантаження, температура, вулиця чи приміщення.</li><li><b>Плановий обсяг</b> — партія та річна потреба. Від цього залежить кількість гнізд і клас форми.</li><li><b>Вимоги до точності та поверхні</b> — критичні розміри, глянець, текстура, видимі зони, де небажані сліди ливника.</li><li><b>Колір</b> і, за наявності, вимоги до маркування.</li><li><b>Бажані терміни</b> першої партії.</li>"], ["blockquote", "<p>Чим повніше технічне завдання, тим точніший розрахунок і менше сюрпризів на етапі пробного лиття.</p>"], ["h3", "Немає креслення? Працюємо зі зразком"], ["p", "Якщо у вас є лише фізичний зразок, ми виконаємо обмір і побудуємо 3D-модель. На цьому ж етапі можна виправити недоліки оригіналу — потоншити надто масивні стінки, додати ребра жорсткості чи ухили."], ["h2", "Від чого залежить вартість пресформи"], ["ul", "<li><b>Розміри та складність виробу.</b> Більша й складніша деталь — більші плити, довша механічна обробка.</li><li><b>Кількість гнізд.</b> Багатогніздна форма дорожча, але дає дешевшу деталь на великих тиражах.</li><li><b>Піднутрення та рухомі елементи.</b> Кожен повзун чи знак — це додатковий вузол.</li><li><b>Тип ливникової системи.</b> Гарячі канали дорожчі, але економлять матеріал і скорочують цикл.</li><li><b>Сталь і ресурс.</b> Для великих тиражів формоутворні частини виготовляють із загартованих інструментальних сталей, для менших — можна обрати простіше рішення.</li><li><b>Вимоги до поверхні й точності.</b> Полірування, текстурування, жорсткі допуски збільшують обсяг робіт.</li>"], ["h3", "Одногніздна чи багатогніздна форма"], ["p", "Одногніздна форма дешевша й швидша у виготовленні, її легше доводити. Багатогніздна виправдана, коли річний обсяг вимірюється десятками й сотнями тисяч деталей. Ми порахуємо обидва варіанти, щоб ви бачили загальну вартість проєкту, а не лише ціну форми."], ["h2", "Етапи та терміни виготовлення"], ["ol", "<li><b>Аналіз і комерційна пропозиція</b> — оцінюємо технологічність, погоджуємо конструкцію, вартість і терміни.</li><li><b>Проєктування</b> — 3D-модель пресформи, розрахунок ливникової системи й охолодження, погодження із замовником.</li><li><b>Виготовлення</b> — фрезерування на верстатах із ЧПК, електроерозійна обробка, шліфування, термообробка.</li><li><b>Складання й налагодження</b> — збирання вузлів, перевірка рухомих елементів і систем охолодження.</li><li><b>Пробне лиття</b> — перші відливки, вимірювання, за потреби — доведення форми.</li><li><b>Передача або серія</b> — форма переходить у серійне виробництво на нашому обладнанні чи передається вам.</li>"], ["p", "Загальний термін залежить від складності: проста форма виготовляється за кілька тижнів, складна багатогніздна — довше. Точний графік зафіксуємо в пропозиції."], ["cta", "{\"t\": \"Маєте креслення чи зразок?\", \"d\": \"Ознайомтеся з послугами або одразу надішліть файли — розрахуємо пресформу й лиття.\", \"b\": [[\"Виготовлення пресформ\", \"srv1\", \"soon\", \"1\", \"/vyhotovlennia-presform\"], [\"Лиття пластикових виробів\", \"srv0\", \"soon\", \"0\", \"/lyttia-plastyku\"], [\"Надіслати креслення\", \"rfq\"]]}"], ["h2", "Як скоротити терміни й бюджет"], ["ul", "<li>Закладайте технологічність у конструкцію: рівні стінки, ухили, радіуси.</li><li>Уникайте піднутрень, без яких можна обійтися, — кожне додає рухомий вузол.</li><li>Розгляньте сімейну форму, якщо кілька деталей виготовляються в однаковому матеріалі й кольорі.</li><li>Почніть із прототипу, якщо конструкція ще не остаточна: зміни до металу обходяться значно дешевше.</li>"], ["h2", "Кому належить пресформа"], ["p", "Пресформа, виготовлена й оплачена під ваш виріб, належить вам. Ви можете забрати її на власне підприємство або залишити в нас — тоді ми відливатимемо партії на своєму обладнанні й зберігатимемо форму між замовленнями. Як проходить сам процес лиття, ми описали в статті <a href=\"/blog/lyttia-pid-tyskom\" data-go=\"post\" data-a=\"3\">«Лиття пластмас під тиском»</a>."], ["h2", "Часті питання"], ["h3", "Скільки коштує пресформа?"], ["p", "Однозначної ціни немає: вона залежить від розмірів, складності, кількості гнізд і вимог до ресурсу. Після аналізу креслення ми надаємо пропозицію з розбивкою вартості."], ["h3", "Чи можна змінити виріб після виготовлення форми?"], ["p", "Частково — так, якщо зміни зводяться до видалення металу (поглиблення, подовження). Додавати метал складніше, тому основні рішення краще погодити до початку виготовлення."], ["h3", "Скільки циклів витримує пресформа?"], ["p", "Ресурс закладається на етапі проєктування під ваш плановий тираж і залежить від сталі, матеріалу виробу та умов експлуатації."], ["h2", "Висновок"], ["p", "Добре підготовлене звернення — це креслення або зразок, матеріал, обсяг і вимоги до точності. З ними ми швидко підготуємо пропозицію, а після погодження — спроєктуємо, виготовимо й запустимо форму у виробництво. Заповніть форму нижче, щоб отримати розрахунок."]], [["p", "The mold is the tool that defines the quality of every part it makes. Design mistakes are hard and costly to fix later, so preparing the request matters as much as the build itself."], ["p", "This article explains what an injection mold consists of, what to prepare for your first enquiry, what drives cost and lead time and how to shorten the road to series production. More about the service: <a href=\"/en/mold-making\" data-go=\"soon\" data-a=\"1\">Mold making</a>."], ["h2", "What a mold consists of"], ["ul", "<li><b>Cavity and core inserts</b> — form the outer and inner surfaces of the part.</li><li><b>Runner system</b> — channels that deliver the melt; cold or hot runner.</li><li><b>Cooling system</b> — channels that control cycle time and dimensional stability.</li><li><b>Ejection system</b> — pins, plates and strippers that remove the part.</li><li><b>Moving elements</b> — slides and lifters for undercuts, side holes and threads.</li><li><b>Mold base</b> — the plate stack that holds everything and mounts on the machine.</li>"], ["h2", "What to prepare"], ["ol", "<li><b>Drawing or 3D model</b> — ideally STEP or IGES, plus a PDF with dimensions and tolerances.</li><li><b>Material</b> — the grade, or at least operating conditions: load, temperature, indoor or outdoor.</li><li><b>Planned volume</b> — batch size and annual demand; this sets cavity count and mold class.</li><li><b>Accuracy and surface requirements</b> — critical dimensions, gloss, texture, visible areas where gate marks are unwanted.</li><li><b>Colour</b> and any marking requirements.</li><li><b>Target date</b> for the first batch.</li>"], ["blockquote", "<p>The fuller the brief, the more accurate the quote and the fewer surprises at the trial stage.</p>"], ["h3", "No drawing? We work from a sample"], ["p", "If you only have a physical sample, we will measure it and build a 3D model — and can fix the original’s weaknesses along the way, such as thick walls, missing ribs or draft."], ["h2", "What drives mold cost"], ["ul", "<li><b>Part size and complexity</b> — larger plates, longer machining.</li><li><b>Number of cavities</b> — a multi-cavity mold costs more but cuts unit price on large runs.</li><li><b>Undercuts and moving elements</b> — each slide or lifter is an extra assembly.</li><li><b>Runner type</b> — hot runners cost more but save material and cycle time.</li><li><b>Steel and tool life</b> — hardened tool steels for long runs, simpler options for smaller ones.</li><li><b>Surface and accuracy</b> — polishing, texturing and tight tolerances add work.</li>"], ["h3", "Single or multi-cavity"], ["p", "A single-cavity mold is cheaper, faster to build and easier to tune. Multi-cavity pays off when annual volume reaches tens or hundreds of thousands of parts. We will price both so you see the total project cost, not just the mold."], ["h2", "Stages and lead times"], ["ol", "<li><b>Review and quote</b> — manufacturability, design, price and timing.</li><li><b>Design</b> — 3D mold model, runner and cooling layout, customer approval.</li><li><b>Manufacturing</b> — CNC milling, EDM, grinding, heat treatment.</li><li><b>Assembly and setup</b> — fitting assemblies, checking moving parts and cooling.</li><li><b>Trial molding</b> — first shots, measurement and adjustments if needed.</li><li><b>Handover or production</b> — the mold goes into series production with us or is handed over to you.</li>"], ["p", "A simple mold takes a few weeks; a complex multi-cavity tool takes longer. The exact schedule is fixed in the quote."], ["cta", "{\"t\": \"Have a drawing or sample?\", \"d\": \"Explore our services or send files right away — we will quote the mold and molding.\", \"b\": [[\"Mold making\", \"srv1\", \"soon\", \"1\", \"/en/mold-making\"], [\"Injection molding\", \"srv0\", \"soon\", \"0\", \"/en/injection-molding\"], [\"Send a drawing\", \"rfq\"]]}"], ["h2", "How to save time and budget"], ["ul", "<li>Design for manufacturing: even walls, draft, radii.</li><li>Avoid undercuts you do not need — each adds a moving assembly.</li><li>Consider a family mold for several parts in the same material and colour.</li><li>Start with a prototype if the design is not final — changes before steel are far cheaper.</li>"], ["h2", "Who owns the mold"], ["p", "A mold made and paid for your part is yours. You can take it to your own plant or keep it with us — we will mold batches on our equipment and store the tool between orders. How molding itself works is covered in <a href=\"/en/blog/injection-molding-process\" data-go=\"post\" data-a=\"3\">“Plastic injection molding”</a>."], ["h2", "FAQ"], ["h3", "How much does a mold cost?"], ["p", "There is no single price: it depends on size, complexity, cavities and tool life. After reviewing the drawing we send a quote with a cost breakdown."], ["h3", "Can the part be changed after the mold is built?"], ["p", "Partly — if changes mean removing steel (deeper, longer features). Adding steel is harder, so key decisions are best agreed before manufacturing."], ["h3", "How many cycles does a mold last?"], ["p", "Tool life is designed in for your planned volume and depends on the steel, the plastic and operating conditions."], ["h2", "Conclusion"], ["p", "A well-prepared enquiry includes a drawing or sample, material, volume and accuracy requirements. With these we can quote quickly and then design, build and launch the mold. Fill in the form below to get a quote."]]], "tag": ["Пресформи", "Molds"]}], "faqs": [{"c": "gen", "q": {"uk": "Як отримати розрахунок вартості?", "en": "How do I get a quote?"}, "a": {"uk": "Залиште заявку на сайті, напишіть на email або зателефонуйте. Вкажіть потрібні вироби та обсяги або прикріпіть креслення — менеджер зв’яжеться з вами в робочий час і підготує комерційну пропозицію.", "en": "Send a request on the website, email us or call. List the items and volumes or attach a drawing — a manager will get back to you during working hours with a quote."}, "on": true}, {"c": "gen", "q": {"uk": "Чи працюєте ви з компаніями та ФОП?", "en": "Do you work with companies and sole traders?"}, "a": {"uk": "Так. Ми співпрацюємо з будівельними компаніями, постачальниками будматеріалів, виробниками та приватними замовниками. Усі закривальні документи надаємо разом із відвантаженням.", "en": "Yes. We work with construction companies, building-material suppliers, manufacturers and private clients, and provide all closing documents with the shipment."}, "on": true}, {"c": "gen", "q": {"uk": "Де розташована компанія?", "en": "Where are you located?"}, "a": {"uk": "Офіси PLASTIZA працюють у Львові (вул. Шевченка, 154) та Києві (пров. Ю. Матущака, 18). Зустріч з менеджером радимо попередньо погодити телефоном.", "en": "PLASTIZA has offices in Lviv (154 Shevchenka St.) and Kyiv (18 Yu. Matushchaka Ln.). Please arrange a meeting with a manager in advance."}, "on": true}, {"c": "prod", "q": {"uk": "Як обрати потрібний фіксатор арматури?", "en": "How do I choose the right rebar spacer?"}, "a": {"uk": "Вибір залежить від основи та положення арматури: «Настил» — для сипучої основи, «Стійка», «Защіпка» й «Засувка» — для горизонтальної арматури на твердій основі, «Зірочка» — для вертикальних елементів. Менеджер допоможе підібрати розмір під проєктний захисний шар бетону.", "en": "It depends on the base and rebar position: “Nastil” for loose bases; “Stiika”, “Zashchipka” and “Zasuvka” for horizontal rebar on solid bases; “Zirochka” for vertical elements."}, "on": true}, {"c": "prod", "q": {"uk": "Яка мінімальна партія замовлення?", "en": "What is the minimum order?"}, "a": {"uk": "Фіксатори постачаємо упаковками: від 100 до 2000 шт. залежно від виробу та розміру. Точне фасування вказане в картці кожного товару. Для нестандартних виробів обсяг партії погоджуємо індивідуально.", "en": "Spacers ship in packs of 100 to 2,000 pcs depending on the item and size; the exact pack size is shown on each product card."}, "on": true}, {"c": "prod", "q": {"uk": "Скільки фіксаторів потрібно на 1 м²?", "en": "How many spacers per m²?"}, "a": {"uk": "Орієнтовна витрата горизонтальних фіксаторів — 4–6 шт. на м² залежно від кроку арматури та навантаження. Для точного розрахунку надішліть креслення або специфікацію.", "en": "Typical consumption of horizontal spacers is 4–6 pcs per m², depending on rebar spacing and load."}, "on": true}, {"c": "prod", "q": {"uk": "Чи надаєте ви документи якості на продукцію?", "en": "Do you provide quality documents?"}, "a": {"uk": "Так, документи, що підтверджують якість продукції, надаємо на запит. Уточніть у менеджера, які саме документи потрібні для вашого об’єкта.", "en": "Yes, documents confirming product quality are available on request."}, "on": true}, {"c": "mfg", "q": {"uk": "Чи можна виготовити виріб за моїм кресленням?", "en": "Can you make a part from my drawing?"}, "a": {"uk": "Так. Надішліть креслення, 3D-модель або зразок — ми оцінимо технологічність, підготуємо розрахунок вартості пресформи й лиття та погодимо терміни. Можемо почати з прототипу, щоб перевірити виріб до запуску серії.", "en": "Yes. Send a drawing, a 3D model or a sample — we’ll assess manufacturability, quote the mold and molding and agree on lead times."}, "on": true}, {"c": "mfg", "q": {"uk": "Скільки коштує виготовлення пресформи?", "en": "How much does a mold cost?"}, "a": {"uk": "Вартість залежить від розмірів і складності виробу, кількості гнізд та вимог до точності. Після аналізу креслення ми надаємо комерційну пропозицію з вартістю й термінами.", "en": "It depends on part size and complexity, cavity count and precision; we quote after reviewing the drawing."}, "on": true}, {"c": "mfg", "q": {"uk": "Чи можете ви лити в моїй пресформі або передати пресформу мені?", "en": "Can you mold in my mold or hand the mold over?"}, "a": {"uk": "Так, обидва варіанти можливі. Пресформу, виготовлену під ваш виріб, можемо передати для використання на вашому підприємстві або відлити партію на нашому обладнанні й передати вам готову продукцію для реалізації.", "en": "Both are possible: we can hand the mold over or run the batch and deliver finished products."}, "on": true}, {"c": "mfg", "q": {"uk": "Які терміни виготовлення?", "en": "What are the lead times?"}, "a": {"uk": "Для виробів із каталогу терміни залежать від обсягу партії, для нових виробів — від складності пресформи та тиражу. Точні терміни фіксуємо в комерційній пропозиції.", "en": "For catalog items lead time depends on batch size; for new parts on mold complexity and volume. Exact dates are fixed in the quote."}, "on": true}, {"c": "del", "q": {"uk": "Як здійснюється доставка?", "en": "How is delivery handled?"}, "a": {"uk": "Доставляємо по всій Україні зручним для вас способом: службами доставки, транспортною компанією або транспортом за домовленістю. Умови та вартість доставки погоджуємо під час оформлення замовлення.", "en": "We deliver across Ukraine by courier services, freight carriers or transport by arrangement; terms are agreed when you order."}, "on": true}, {"c": "del", "q": {"uk": "Які умови оплати?", "en": "What are the payment terms?"}, "a": {"uk": "Пропонуємо гнучкі умови оплати, зручні для вашої компанії: безготівковий розрахунок на рахунок для юридичних осіб і ФОП. Для постійних клієнтів можливі індивідуальні умови.", "en": "Flexible terms that suit your company, including bank transfer for businesses; individual terms are available for regular clients."}, "on": true}, {"c": "del", "q": {"uk": "Чи можна забрати замовлення самостійно?", "en": "Can I collect the order myself?"}, "a": {"uk": "Так, самовивіз можливий за попереднім погодженням часу з менеджером.", "en": "Yes, pickup is possible by prior arrangement with a manager."}, "on": true}]};
